import hashlib
import subprocess
import tempfile
import urllib.request
from pathlib import Path

ANTLR_URL = 'https://www.antlr.org/download/antlr-4.9.3-complete.jar'
ANTLR_SHA256 = 'afcd40946d3de4d81e28d7c88d467289e0587285d27adb172aecc5494a17df36'
PYTHON_HEADER = '''# SPDX-FileCopyrightText: Copyright (c) 2026, NVIDIA CORPORATION & AFFILIATES.
# All rights reserved.
# SPDX-License-Identifier: Apache-2.0
# @generated by ANTLR 4.9.3 — DO NOT EDIT.

'''


def normalize_generated_file(path: Path) -> None:
    content = path.read_text()
    if path.name == 'PQLGrammarVisitor.py':
        content = content.replace(
            'else:\n    from PQLGrammarParser import PQLGrammarParser',
            'else:\n    from PQLGrammarParser import '
            'PQLGrammarParser  # pants: no-infer-dep')
    if path.suffix == '.py' and not content.startswith(PYTHON_HEADER):
        content = PYTHON_HEADER + content
    lines = [line.rstrip() for line in content.splitlines()]
    while lines and not lines[-1]:
        lines.pop()
    path.write_text('\n'.join(lines) + '\n')


def main() -> None:
    grammar_dir = Path(__file__).parents[1] / 'kumopql' / 'grammar'
    with tempfile.TemporaryDirectory() as directory:
        jar = Path(directory) / 'antlr.jar'
        urllib.request.urlretrieve(ANTLR_URL, jar)
        if hashlib.sha256(jar.read_bytes()).hexdigest() != ANTLR_SHA256:
            raise RuntimeError('ANTLR checksum mismatch')
        subprocess.run([
            'java', '-jar', str(jar), '-Dlanguage=Python3', '-visitor',
            '-no-listener', 'PQLGrammar.g4'
        ], cwd=grammar_dir, check=True)
    for generated in grammar_dir.glob('PQLGrammar*'):
        if generated.name != 'PQLGrammar.g4':
            normalize_generated_file(generated)


if __name__ == '__main__':
    main()
